(function(){
'use strict';
const D=window.GATE_DATA, C=window.GateCore, $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
if(!D){$('#app').innerHTML='<p class="boot">Study data could not load. Extract the entire ZIP before opening index.html.</p>';return;}
const topicMap=new Map(D.topics.map(t=>[t.id,t])), qMap=new Map(D.questions.map(q=>[q.id,q]));
const subjectNames=D.subjects.map(s=>s.name),topicQs=new Map(D.topics.map(t=>[t.id,[]]));
const topicsBySubject=new Map(subjectNames.map(name=>[name,[]])),questionsBySubject=new Map(subjectNames.map(name=>[name,[]])),groupsBySubject=new Map(subjectNames.map(name=>[name,new Map()]));
for(const t of D.topics){topicsBySubject.get(t.subject)?.push(t);const groups=groupsBySubject.get(t.subject);if(groups){if(!groups.has(t.group))groups.set(t.group,[]);groups.get(t.group).push(t);}}
for(const q of D.questions){topicQs.get(q.subtopicId)?.push(q);const t=topicMap.get(q.subtopicId);if(t)questionsBySubject.get(t.subject)?.push(q);}
const STORE='gate-recall-progress-v1';let storageOK=true,state;
try{const saved=JSON.parse(localStorage.getItem(STORE)||'null');state=saved?C.safeProgress({app:'gate-recall',version:1,state:saved},new Set(qMap.keys()),new Set(topicMap.keys())):null;}catch(e){storageOK=false;}
state=state||{questions:{},cards:{},sessions:[],settings:{},last:null};
let openSubject=null,activeTab='theory',currentQ=null,revealed=false,cardReveal=false,query='',filters={paper:'All',year:'All',type:'All',status:'All'},shownQuestions=[],isReview=false,reviewQueue=[],reviewIndex=0,downloadJob=null,deferredInstall=null,saveTimer,routeKey='';
const icons={'Engineering Mathematics':'∑','Digital Logic':'01','Computer Organization and Architecture':'▦','Programming and Data Structures':'{ }','Algorithms':'⌁','Theory of Computation':'δ','Compiler Design':'⟨ ⟩','Operating System':'⊞','Databases':'▤','Computer Networks':'⌘','General Aptitude':'Aa'};
const shortNames={'Computer Organization and Architecture':'Computer Organization','Programming and Data Structures':'Programming & Data Structures','Engineering Mathematics':'Engineering Mathematics'};
function qs(id){return state.questions[id]||{};}function cs(id){return state.cards[id]||{};}function fmt(n){return Number(n).toLocaleString('en-IN');}
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('Progress could not be saved. Export a backup now.');}}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function logReview(){const date=localDate();let x=state.sessions.find(s=>s.date===date);if(!x)state.sessions.push(x={date,count:0});x.count++;}
function dueItems(){const now=Date.now();return [...Object.entries(state.cards).filter(([id,p])=>topicMap.has(id)&&p.due&&p.due<=now).map(([id,p])=>({kind:'card',id,due:p.due})),...Object.entries(state.questions).filter(([id,p])=>qMap.has(id)&&p.due&&p.due<=now).map(([id,p])=>({kind:'question',id,due:p.due}))].sort((a,b)=>a.due-b.due);}
function subjectTopics(name){return topicsBySubject.get(name)||[];}function subjectQ(name){return questionsBySubject.get(name)||[];}
function percent(done,total){return total?Math.round(100*done/total):0;}function completed(q){return qs(q.id).result==='correct';}
function groupsFor(name){return groupsBySubject.get(name)||new Map();}
function hrefTopic(id,tab='theory',qid){return '#topic/'+id+'/'+tab+(qid?'/'+qid:'');}
function nowRoute(){const h=location.hash.slice(1).split('/');return {kind:h[0]||'home',id:h[1]?decodeURIComponent(h[1]):null,tab:h[2]||'theory',qid:h[3]||null};}
function shell(content,nav='home'){
 const due=dueItems().length;
 return `<div class="layout"><aside class="sidebar" aria-label="Study navigation"><a href="#home" class="brand"><img src="icon.svg" alt=""><span>GATE Recall<sup>YOUR PERSONAL STUDY DESK</sup></span></a><nav><a class="nav-row ${nav==='home'?'active':''}" href="#home"><span class="nav-icon">▦</span> Study desk</a><a class="nav-row ${nav==='review'?'active':''}" href="#review"><span class="nav-icon">↻</span> Daily review ${due?`<span class="badge">${due}</span>`:''}</a><a class="nav-row ${nav==='saved'?'active':''}" href="#saved"><span class="nav-icon">☆</span> Saved & mistakes</a><div class="nav-caption">Explore the syllabus</div>${D.subjects.map(s=>{const open=openSubject===s.name;return `<div><button class="subject-toggle ${open?'active':''}" data-action="subject" data-name="${esc(s.name)}" aria-expanded="${open}"><span class="subicon">${icons[s.name]||'·'}</span><span>${esc(shortNames[s.name]||s.name)}</span><span class="chevron">›</span></button>${open?`<div class="tree-groups">${[...groupsFor(s.name)].map(([g,ts])=>`<details class="tree-group" ${ts.some(t=>t.id===nowRoute().id)?'open':''}><summary>${esc(g)}</summary>${ts.map(t=>`<a class="tree-leaf ${t.id===nowRoute().id?'active':''}" href="${hrefTopic(t.id)}"><span>${esc(t.title)}</span><span>${topicQs.get(t.id).length}</span></a>`).join('')}</details>`).join('')}</div>`:''}</div>`;}).join('')}</nav><div class="sidebar-bottom"><div class="footnote">Recall first. Understand. Try again.</div></div></aside><div class="main-shell"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">☰</button><form class="searchbox" id="search-form" role="search"><span aria-hidden="true">⌕</span><input id="search" aria-label="Search topics and questions" placeholder="Search topics, concepts, or a PYQ…" value="${esc(query)}" autocomplete="off"><kbd>/</kbd></form><div class="top-actions"><span class="connection" id="connection">${location.protocol==='file:'?'Local copy':navigator.onLine?'Device progress saved locally':'Offline mode'}</span><details class="profile-menu" id="profile-menu"><summary class="profile-trigger" aria-label="Profile and settings"><span class="avatar" id="avatar-text">${esc(state.settings.initials||'GR')}</span><span class="profile-arrow" aria-hidden="true">⌄</span></summary><div class="profile-popover"><div class="profile-heading"><span class="profile-heading-icon">✦</span><div><strong>Your study space</strong><small>Personal to this browser</small></div></div><form id="profile-form" class="profile-form"><label for="profile-initials">Your initials</label><div class="profile-edit"><input id="profile-initials" name="initials" maxlength="3" value="${esc(state.settings.initials||'GR')}" autocomplete="off" aria-describedby="initials-hint initials-error"><button class="secondary" type="submit">Save</button></div><small id="initials-hint">1–3 letters or numbers · saved on this device</small><span id="initials-error" class="profile-error" role="status"></span></form><nav class="profile-links" aria-label="Profile navigation"><a href="#my-notes"><span class="profile-link-icon">✎</span><span><strong>My PYQ notes</strong><small>Your notes, grouped by subject</small></span><span aria-hidden="true">→</span></a><a href="#settings"><span class="profile-link-icon">↓</span><span><strong>Offline & backup</strong><small>Download and keep your progress</small></span><span aria-hidden="true">→</span></a><a href="#sources"><span class="profile-link-icon">▧</span><span><strong>Sources & corrections</strong><small>Books, coverage and fixes</small></span><span aria-hidden="true">→</span></a></nav></div></details></div></header><main id="main" class="page" tabindex="-1">${!storageOK?'<div class="notice">Browser storage is unavailable. Keep this tab open and export your progress before closing.</div>':''}${content}</main></div></div>`;
}
function header(eyebrow,title,sub,right=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`;}
function crumb(t){return `<div class="breadcrumb"><a href="#home">Study desk</a><span>›</span><a href="#subject/${encodeURIComponent(t.subject)}">${esc(t.subject)}</a><span>›</span><span>${esc(t.group)}</span></div>`;}
function dashboard(){
 const due=dueItems().length,done=D.questions.filter(completed).length,attempted=Object.values(state.questions).filter(p=>p.attempted).length,today=state.sessions.find(s=>s.date===localDate())?.count||0;
 const recent=state.last&&topicMap.get(state.last),date=new Date();
 return header('A LITTLE PRACTICE, EVERY DAY','Make it stick.','Pick a concept. Recall it. Put it to the test.',`<div class="date-tag">${date.toLocaleDateString('en-IN',{weekday:'long'})}<strong>${date.toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}</strong></div>`)+`<div class="welcome"><section class="review-hero"><div><div class="eyebrow">YOUR NEXT SMALL STEP</div><h2>${due?`${due} things to revisit.`:recent?'Pick up where you left off.':'Start with what you know.'}</h2><p>${due?'A short recall session keeps familiar ideas from slipping away.':recent?esc(recent.title)+' · '+esc(recent.subject):'Build understanding one subtopic at a time. Your review queue grows as you practise.'}</p><a class="primary" href="${due?'#review':recent?hrefTopic(recent.id):'#subject/Engineering%20Mathematics'}">${due?'Start daily review':recent?'Continue learning':'Explore mathematics'} <span>→</span></a></div><div class="hero-art" aria-hidden="true"><div class="card-stack back"></div><div class="card-stack"><span class="rule"></span></div></div></section><section class="progress-panel"><div class="progress-heading">Your progress <span class="muted small">All time</span></div><div class="metrics"><div class="metric"><strong>${fmt(attempted)}</strong><span>PYQs attempted</span></div><div class="metric"><strong>${today}</strong><span>Reviews today</span></div><div class="metric"><strong>${percent(done,D.questions.length)}<span>%</span></strong><span>Marked correct</span></div></div><div><div class="progress-track"><i style="width:${percent(done,D.questions.length)}%"></i></div><div class="small muted" style="font-size:10px;margin-top:8px">${fmt(done)} of ${fmt(D.questions.length)} source entries marked correct</div></div></section></div><div class="section-heading"><h2>Your syllabus</h2><small>${D.subjects.length} subjects · ${D.topics.length} subtopics · ${fmt(D.questions.length)} question entries</small></div><div class="subject-grid">${D.subjects.map(s=>{const ts=subjectTopics(s.name),qq=subjectQ(s.name),n=qq.filter(completed).length;return `<a class="subject-card" href="#subject/${encodeURIComponent(s.name)}"><div class="subject-card-top"><span class="subject-icon">${icons[s.name]}</span><span class="arrow">↗</span></div><h3>${esc(shortNames[s.name]||s.name)}</h3><div class="meta">${groupsFor(s.name).size} topics <span aria-hidden="true">·</span> ${ts.length} subtopics <span aria-hidden="true">·</span> ${qq.length} PYQs</div><div class="progress-track"><i style="width:${percent(n,qq.length)}%"></i></div><div class="progress-label"><span>${n?`${n} marked correct`:'Ready when you are'}</span><span>${percent(n,qq.length)}%</span></div></a>`;}).join('')}</div><div class="practice-tip"><span aria-hidden="true">✧</span><div><strong>A better recall habit</strong> &nbsp; Before revealing an answer, say the rule out loud or write the first step. Recognition is easier than recall.</div></div><div class="footer-line">Based on your supplied syllabus and three PYQ volumes. Includes CSE, IT, DA and additional papers; use practice filters to choose.</div>`;
}
function subjectView(name){const s=D.subjects.find(s=>s.name===name);if(!s)return notFound();const ts=subjectTopics(name),qq=subjectQ(name);return `<div class="breadcrumb"><a href="#home">Study desk</a><span>›</span><span>${esc(name)}</span></div>`+header('EXPLORE A SUBJECT',name,`${groupsFor(name).size} topics · ${ts.length} subtopics · ${qq.length} source questions`)+`<p class="syllabus-text">${esc(s.syllabus)}</p><div class="section-space">${[...groupsFor(name)].map(([g,list],i)=>`<details class="topic-group" ${i===0?'open':''}><summary>${esc(g)}<span>${list.length} subtopics</span></summary><div class="leaf-list">${list.map(t=>`<a class="leaf-row" href="${hrefTopic(t.id)}"><div><strong>${esc(t.title)}</strong><small>${esc(t.cue)}</small></div><div><span class="pill ${t.scope==='extra'?'extra':''}">${topicQs.get(t.id).length} PYQs</span> <span class="muted">›</span></div></a>`).join('')}</div></details>`).join('')}</div>`;}
function correctionBox(t){if(!t.correction)return '';const c=t.correction;return `<div class="correction"><strong>Corrected from the supplied notes · volume ${t.volume}, p. ${esc(c.sourcePage)}</strong><p>${esc(c.corrected)}</p><details><summary>What changed and why</summary><p>Source: ${esc(c.original)}</p><p>${esc(c.reason)}</p></details></div>`;}
function ratingButtons(kind,id,prev){return `<div class="rating-buttons" aria-label="Rate your recall">${['again','hard','good','easy'].map(r=>{const next=C.schedule(prev,r);return `<button data-action="rate" data-kind="${kind}" data-id="${id}" data-rating="${r}">${r[0].toUpperCase()+r.slice(1)}<span>${r==='again'?'10 min':next.interval+(next.interval===1?' day':' days')}</span></button>`;}).join('')}</div>`;}
function theoryView(t){const p=cs(t.id);return `<div class="study-layout"><div>${correctionBox(t)}<section class="panel"><div class="eyebrow">RECOGNISE THE QUESTION</div><div class="recognition">${esc(t.cue)}</div><h2>The essential idea</h2><ul class="theory-list">${t.theory.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="recall-card"><div class="eyebrow">CLOSE THE NOTES. TRY TO RECALL.</div><div class="recall-question">${esc(t.recall.q)}</div>${cardReveal?`<div class="revealed">${esc(t.recall.a)}</div><div class="small muted top-spacer">How well did you remember this?</div>${ratingButtons('card',t.id,p)}`:`<button class="primary" data-action="reveal-card">Reveal answer <span>↗</span></button><span class="kbdhint"> &nbsp; Think first.</span>`}${p.reviewed?`<div class="card-result">Reviewed ${new Date(p.reviewed).toLocaleDateString('en-IN')} · next ${new Date(p.due).toLocaleDateString('en-IN')}</div>`:''}</section><label class="field-label" for="topic-note">Your memory cue / explanation in your words</label><textarea class="note-input" id="topic-note" data-note-kind="card" data-note-id="${t.id}" placeholder="What would help you recall this next time?">${esc(p.note||'')}</textarea><div class="note-saved" id="note-saved"></div></div><aside class="study-aside"><div class="aside-box"><div class="eyebrow">WATCH FOR THIS</div><p>${esc(t.pitfall)}</p></div><div class="aside-box"><h3>Put it into practice</h3><p>${topicQs.get(t.id).length} related question entries from your books.</p><a class="secondary" href="${hrefTopic(t.id,'practice')}">Solve a PYQ →</a></div><div class="aside-box"><h3>Where this fits</h3><p>${esc(t.group)}<br><span class="pill ${t.scope==='extra'?'extra':''}">${t.scope==='extra'?'PYQ extension':t.scope==='additional'?'Additional aptitude':'Syllabus topic'}</span></p><p>Concise recall notes accompany the original source notes. Answer keys remain the book’s keys.</p><a href="${hrefTopic(t.id,'notes')}" class="source-link">Read the original notes →</a>${(t.sources||[]).map(s=>{const u=typeof s==='string'?s:s.url;return u&&/^https?:\/\//.test(u)?`<br><a class="source-link" href="${esc(u)}" target="_blank" rel="noopener">Reference ↗</a>`:'';}).join('')}</div></aside></div>`;}
function topicView(t,tab,qid){
 if(!t)return notFound();activeTab=tab;state.last=t.id;save();
 const count=topicQs.get(t.id).length;
 return crumb(t)+header(esc(t.group).toUpperCase(),t.title,`${count} source questions · volume ${t.volume}`,`<button class="secondary" data-action="star-card" data-id="${t.id}">${cs(t.id).star?'★ Saved':'☆ Save topic'}</button>`)+`<div class="tabs" role="navigation" aria-label="Study mode"><a class="tab ${tab==='theory'?'active':''}" href="${hrefTopic(t.id)}">Theory & recall</a><a class="tab ${tab==='practice'?'active':''}" href="${hrefTopic(t.id,'practice')}">Practise PYQs <span class="badge">${count}</span></a><a class="tab ${tab==='notes'?'active':''}" href="${hrefTopic(t.id,'notes')}">Original notes</a></div>${tab==='practice'?practiceView(t,qid):tab==='notes'?sourceNotes(t):theoryView(t)}`;
}
function notFound(){return '<div class="empty"><h2>This page was not found.</h2><a href="#home">Return to your study desk</a></div>';}
function option(value,label,selected){return `<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;}
function filterQuestions(list,directId){return list.filter(q=>(filters.paper==='All'||q.paper===filters.paper)&&(filters.year==='All'||String(q.year)===filters.year)&&(filters.type==='All'||q.type===filters.type)&&(filters.status==='All'||filters.status==='unseen'&&!qs(q.id).attempted||filters.status==='wrong'&&qs(q.id).result==='wrong'||filters.status==='saved'&&qs(q.id).star)&&(!state.settings.hideRecent||!q.year||q.year<=2023||q.id===directId));}
function practiceView(t,qid){
 const all=topicQs.get(t.id);shownQuestions=filterQuestions(all,qid);if(qid&&shownQuestions.some(q=>q.id===qid))currentQ=qid;if(!shownQuestions.some(q=>q.id===currentQ))currentQ=shownQuestions[0]?.id;
 const q=qMap.get(currentQ),years=[...new Set(all.map(q=>q.year).filter(Boolean))].sort((a,b)=>b-a);
 return `<div class="filters"><label class="sr-only" for="paper-filter">Paper</label><select id="paper-filter" data-filter="paper">${['All','CSE','IT','DA','Other','Practice'].map(x=>option(x,x==='All'?'All papers':x,filters.paper)).join('')}</select><label class="sr-only" for="year-filter">Year</label><select id="year-filter" data-filter="year">${option('All','All years',filters.year)+years.map(y=>option(y,y,filters.year)).join('')}</select><label class="sr-only" for="type-filter">Question type</label><select id="type-filter" data-filter="type">${['All','MCQ','MSQ','NAT','Descriptive'].map(x=>option(x,x==='All'?'All types':x,filters.type)).join('')}</select><label class="sr-only" for="status-filter">Progress filter</label><select id="status-filter" data-filter="status">${[['All','All progress'],['unseen','Not attempted'],['wrong','Mistakes'],['saved','Saved']].map(([v,l])=>option(v,l,filters.status)).join('')}</select><span class="small muted">${shownQuestions.length} of ${all.length} entries</span><button class="text-button" data-action="clear-filters">Reset filters</button></div>${state.settings.hideRecent?'<div class="notice">2024–2026 questions are hidden for mock exams, except a question you open directly. Change this in Offline & backup.</div>':''}${q?questionPanel(q):'<div class="empty"><h2>No questions match.</h2><p>Try a different paper, year or progress filter.</p><button class="secondary" data-action="clear-filters">Show all questions</button></div>'}`;
}
function questionPanel(q,review=false){const p=qs(q.id),answer=p.draft||'',idx=shownQuestions.findIndex(x=>x.id===q.id),t=topicMap.get(q.subtopicId),key=String(q.answer||''),isChoice=q.type!=='NAT'&&q.type!=='Descriptive'&&/^[A-E](\s*[;,]\s*[A-E])*$/.test(key),isMulti=isChoice&&(q.type==='MSQ'||/[;,]/.test(key)),letters=/E/.test(key)?['A','B','C','D','E']:['A','B','C','D'];const result=C.grade(q.answer,answer,q.type);
 return `<div class="study-layout"><div class="panel"><div class="question-top"><div><h3>${esc(q.exam)}</h3><div class="status-info">${q.number?'Question '+esc(q.number)+' · ':''}Volume ${q.volume}, p. ${q.page} · ${q.type}${q.marks?' · '+q.marks+' mark'+(q.marks>1?'s':''):''}</div></div><button class="icon-btn" data-action="star-question" data-id="${q.id}" aria-label="${p.star?'Unsave':'Save'} question">${p.star?'★':'☆'}</button></div>${q.paper==='Practice'?'<div class="notice">The book labels this as practice material, not a past exam question.</div>':''}<div class="question-images">${q.images.map((im,i)=>`<img class="question-image" src="${im.src}" width="${im.width}" height="${im.height}" alt="Original question ${esc(q.exam)} ${esc(q.number)}${q.images.length>1?', part '+(i+1):''}" data-action="zoom" data-src="${im.src}" tabindex="0" role="button" aria-label="Enlarge question image, part ${i+1}">`).join('')}</div><div class="eyebrow">${q.type==='Descriptive'?'WORK OUT YOUR SOLUTION':'YOUR ANSWER'}${isMulti?' · SELECT ALL THAT APPLY':''}</div><div class="answer-row">${isChoice?letters.map(l=>`<button class="answer-choice ${answer.split(';').includes(l)?'selected':''}" data-action="choose" data-value="${l}" data-multi="${isMulti}" aria-pressed="${answer.split(';').includes(l)}">${l}</button>`).join(''):`<input class="answer-text" id="answer-input" aria-label="Your answer" placeholder="${q.type==='NAT'?'Enter a number':'Write your answer or solve on paper'}" value="${esc(answer)}" autocomplete="off">`}${!revealed?'<button class="primary" data-action="reveal-question">Check / reveal key</button>':''}</div>${revealed?`<div class="answer-box ${result===false?'wrong':''}"><p><strong>${result===true?'Matches the book key':result===false?'Does not match the book key':'Book answer key'}</strong></p><p>${!key||/^(N\/A|TBA|X)$/i.test(key)?'No usable answer supplied. Self-assess or check the linked discussion.':esc(key)}</p><small>Transcribed from the supplied book; not independently verified. ${q.answerPage?`<a href="books/volume${q.volume}.pdf#page=${q.answerPage}" target="_blank" rel="noopener">View key page ${q.answerPage}</a>`:''}</small></div><div class="button-row"><button class="secondary" data-action="mark-result" data-value="correct">✓ Mark correct</button><button class="secondary" data-action="mark-result" data-value="wrong">↺ Needs work</button></div><p class="small muted top-spacer">${p.result==='correct'?'Marked correct. ':p.result==='wrong'?'Marked as needing work. ':''}When should you revisit this?</p>${ratingButtons('question',q.id,p)}`:''}<label class="field-label" for="question-note">Your working / what tripped you up</label><textarea id="question-note" class="note-input" data-note-kind="question" data-note-id="${q.id}" placeholder="Record the reasoning, not just the answer.">${esc(p.note||'')}</textarea><div class="note-collection-row"><span class="note-saved" id="note-saved"></span><a href="#my-notes">View all PYQ notes →</a></div><details class="note-details"><summary>Searchable text / accessibility</summary><p class="small muted">The PDF text omits some embedded equations. Use the original image above for exact wording and numbers.</p><p>${esc(q.searchText)}</p></details><div class="question-actions">${review?'<button class="secondary" data-action="review-next">Skip for now →</button>':`<button class="secondary" data-action="prev-q" ${idx<=0?'disabled':''}>← Previous</button><span class="small muted">${idx+1} / ${shownQuestions.length}</span><button class="secondary" data-action="next-q" ${idx>=shownQuestions.length-1?'disabled':''}>Next →</button>`}</div></div><aside class="study-aside"><div class="aside-box"><h3>${review?'In this review':'Question navigator'}</h3>${review?`<p>${esc(t.title)}<br>${reviewIndex+1} of ${reviewQueue.length}</p>`:`<div class="question-nav">${shownQuestions.map((x,i)=>`<button data-action="select-q" data-id="${x.id}" class="${x.id===q.id?'active ':''}${qs(x.id).result||''}" aria-label="Question ${i+1}, ${esc(x.exam)}">${i+1}</button>`).join('')}</div>`}<p class="small" style="margin-top:12px;margin-bottom:0">Green: marked correct · peach: needs work.</p></div><div class="aside-box"><h3>Need the concept?</h3><p>${esc(t.cue)}</p><a class="secondary" href="${hrefTopic(t.id)}">Revisit theory →</a></div><div class="aside-box"><h3>Check the source</h3><a class="source-link" href="books/volume${q.volume}.pdf#page=${q.page}" target="_blank" rel="noopener">Open original PDF · p. ${q.page} ↗</a>${q.discussion?`<br><a class="source-link" href="${esc(q.discussion)}" target="_blank" rel="noopener">Community solution · online ↗</a>`:''}<button class="secondary" data-action="flag-question" data-id="${q.id}">${p.flag?'⚑ Flagged for checking':'Flag a possible error'}</button></div></aside></div>`;
}
let notePage=null;
function sourceNotes(t){const start=t.originalNotes.startPage,end=t.originalNotes.endPage;notePage=Math.max(start,Math.min(end,notePage||start));return `<div class="notice">Original book notes, preserved as supplied. The Theory & recall tab contains the revised recap and any verified correction. This source material has not been exhaustively audited.</div>${correctionBox(t)}<div class="source-toolbar"><span class="small muted">Volume ${t.volume} · source note pages ${start}–${end}</span><a class="secondary" href="books/volume${t.volume}.pdf#page=${notePage}" target="_blank" rel="noopener">Open PDF ↗</a></div><div class="source-toolbar"><button class="secondary" data-action="note-prev" ${notePage<=start?'disabled':''}>← Previous page</button><span>PDF page ${notePage} · ${notePage-start+1} / ${end-start+1}</span><button class="secondary" data-action="note-next" ${notePage>=end?'disabled':''}>Next page →</button></div><div class="source-view"><img src="notes/v${t.volume}/${notePage}.webp" class="source-page" alt="Original notes, volume ${t.volume}, page ${notePage}" data-action="zoom" data-src="notes/v${t.volume}/${notePage}.webp" role="button" tabindex="0" aria-label="Enlarge original notes"></div>`;}
function reviewView(){const due=dueItems();if(isReview){const item=reviewQueue[reviewIndex];if(!item){isReview=false;return header('DAILY REVIEW','Session complete.','You have worked through this review queue.')+'<div class="review-complete"><h2>Let it settle.</h2><p>Your next reviews are scheduled from your ratings.</p><a class="primary" href="#home">Back to study desk →</a></div>';}
 const t=item.kind==='card'?topicMap.get(item.id):topicMap.get(qMap.get(item.id).subtopicId);currentQ=item.kind==='question'?item.id:null;
 return header(`DAILY REVIEW · ${reviewIndex+1} / ${reviewQueue.length}`,t.title,`${esc(t.subject)} · ${item.kind==='card'?'Concept recall':'Question review'}`,`<button class="secondary" data-action="review-end">End session</button>`)+(item.kind==='card'?`<section class="recall-card"><div class="eyebrow">RETRIEVE IT BEFORE YOU READ IT</div><div class="recall-question">${esc(t.recall.q)}</div>${cardReveal?`<div class="revealed">${esc(t.recall.a)}</div>${ratingButtons('card',t.id,cs(t.id))}`:'<button class="primary" data-action="reveal-card">Reveal answer</button>'}</section><div class="button-row"><a class="secondary" href="${hrefTopic(t.id)}">Read the concept</a><button class="secondary" data-action="review-next">Skip for now →</button></div>`:questionPanel(qMap.get(item.id),true));}
 const scheduled=[...Object.values(state.cards),...Object.values(state.questions)].filter(p=>p.due>Date.now()).length;
 return header('SPACED PRACTICE','Your daily review.',`${due.length} due now · ${scheduled} scheduled for later`)+(due.length?`<button class="primary" data-action="review-start">Review ${due.length} items →</button><div class="review-list top-spacer">${due.slice(0,80).map(item=>{const q=item.kind==='question'?qMap.get(item.id):null,t=topicMap.get(q?q.subtopicId:item.id);return `<a class="review-row" href="${hrefTopic(t.id,q?'practice':'theory',q?.id)}"><div><strong>${esc(t.title)}</strong><small>${q?esc(q.exam):esc(t.subject)}</small></div><span class="pill">${q?'PYQ':'Recall card'}</span></a>`;}).join('')}</div>`:'<div class="empty"><h2>Nothing due right now.</h2><p>Rate a recall card or a PYQ to schedule your next visit.</p><a class="primary" href="#home">Explore a subject →</a></div>')+'<p class="source-note-hint top-spacer">Again: 10 minutes · Hard: at least 1 day · Good: initially 3 days · Easy: initially 7 days. Later intervals grow with your rating. This is a simple review schedule, not a predicted exam score.</p>';
}
function savedView(){const cards=D.topics.filter(t=>cs(t.id).star),qq=D.questions.filter(q=>qs(q.id).star||qs(q.id).result==='wrong'||qs(q.id).flag);return header('KEEP THE USEFUL BITS','Saved & mistakes.',`${cards.length} saved concepts · ${qq.length} question entries`)+(!cards.length&&!qq.length?'<div class="empty"><h2>Your personal revision list starts here.</h2><p>Save a topic, star a question, or mark one as needing work.</p></div>':'')+`<div class="review-list">${cards.map(t=>`<a class="review-row" href="${hrefTopic(t.id)}"><div><strong>${esc(t.title)}</strong><small>${esc(t.subject)}</small></div><span class="pill">Saved concept</span></a>`).join('')}${qq.map(q=>`<a class="review-row" href="${hrefTopic(q.subtopicId,'practice',q.id)}"><div><strong>${esc(topicMap.get(q.subtopicId).title)}</strong><small>${esc(q.exam)} · ${esc(q.number)}</small></div><span class="pill ${qs(q.id).result==='wrong'?'error':''}">${qs(q.id).flag?'Flagged':qs(q.id).result==='wrong'?'Needs work':'Saved question'}</span></a>`).join('')}</div>`;}
function myNotesView(){
 const groups=C.questionNotesBySubject(state.questions,qMap,topicMap,subjectNames),count=groups.reduce((total,group)=>total+group.notes.length,0);
 return header('YOUR STUDY JOURNAL','My PYQ notes.',`${count} ${count===1?'note':'notes'} · grouped by subject`)+
  '<p class="journal-intro">Your working and the things that tripped you up, collected from your question practice. Open a question to edit its note.</p>'+
  (count?`<div class="journal-groups">${groups.map((group,index)=>`<details class="journal-group" ${index===0?'open':''}><summary><span class="journal-subject-icon">${esc(icons[group.subject]||'·')}</span><span class="journal-subject-name">${esc(shortNames[group.subject]||group.subject)}</span><span class="journal-count">${group.notes.length} ${group.notes.length===1?'note':'notes'}</span><span class="journal-chevron" aria-hidden="true">⌄</span></summary><div class="journal-entries">${group.notes.map(({question:q,note})=>`<article class="journal-entry"><a class="journal-question" href="${hrefTopic(q.subtopicId,'practice',q.id)}"><span>${esc(q.exam)}${q.number?' · Question '+esc(q.number):''}</span><span>Open PYQ →</span></a><p class="journal-note">${esc(note)}</p></article>`).join('')}</div></details>`).join('')}</div>`:'<div class="empty"><h2>Your PYQ notes will appear here.</h2><p>While practising a question, write in “Your working / what tripped you up”. Your notes will be collected here by subject.</p><a class="primary" href="#home">Explore a subject →</a></div>');
}
function searchView(){const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean),match=s=>words.every(w=>s.toLowerCase().includes(w)),topics=D.topics.filter(t=>match([t.title,t.sourceTitle,t.subject,t.group,t.cue,...t.theory].join(' '))),questions=D.questions.filter(q=>match(q.exam+' '+q.number+' '+q.searchText));return header('FIND A CONCEPT','Search your study desk.',`${topics.length} matching concepts · ${questions.length} matching question entries`)+`<div class="search-results"><h2>Concepts</h2>${topics.slice(0,60).map(t=>`<a class="leaf-row" href="${hrefTopic(t.id)}"><div><strong>${esc(t.title)}</strong><small>${esc(t.subject)} · ${esc(t.group)}</small></div><span class="pill">${topicQs.get(t.id).length} PYQs</span></a>`).join('')||'<p class="muted">No matching concepts.</p>'}<h2 class="top-spacer">Questions</h2>${questions.slice(0,100).map(q=>`<a class="leaf-row" href="${hrefTopic(q.subtopicId,'practice',q.id)}"><div><strong>${esc(q.exam)} · ${esc(q.number)}</strong><small>${esc(topicMap.get(q.subtopicId).title)}</small></div><span class="pill">${q.type}</span></a>`).join('')||'<p class="muted">No matching questions.</p>'}</div>${questions.length>100||topics.length>60?'<p class="small muted">Showing the first matching results. Add another word to narrow the search.</p>':''}`;}
function sourcesView(){const corrections=D.topics.filter(t=>t.correction);return header('KNOW WHAT YOU ARE STUDYING','Sources & corrections.','Your books, their coverage, and the changes made to the recall notes.')+`<section class="panel"><h2>Collection coverage</h2><p class="small muted">${fmt(D.questions.length)} source entries across ${D.topics.length} subtopics. Years found: ${D.meta.minYear}–${D.meta.maxYear}. This is the collection you supplied; it has not been certified as every GATE CSE question ever asked. CSE, IT, DA, other-paper aptitude and practice entries are labeled separately.</p><div class="table-scroll"><table class="source-table"><thead><tr><th>Source</th><th>Pages</th><th>Entries</th><th>Open</th></tr></thead><tbody>${D.meta.volumes.map(v=>`<tr><td>PYQ volume ${v.volume}</td><td>${v.pages}</td><td>${v.count}</td><td><a href="books/volume${v.volume}.pdf" target="_blank" rel="noopener">PDF ↗</a></td></tr>`).join('')}<tr><td>Supplied GATE 2027 CS syllabus</td><td>2</td><td>10 subject sections</td><td><a href="books/syllabus.pdf" target="_blank" rel="noopener">PDF ↗</a></td></tr></tbody></table></div></section><section class="panel"><h2>How to read the content</h2><ul class="help-list"><li>Question cards preserve source page images, including diagrams and equations.</li><li>Recall notes are concise authored summaries. The original notes stay available beside them.</li><li>PYQ extensions are kept even where they are not explicitly listed in your syllabus.</li><li>Book answer keys are transcribed, not independently re-solved. Missing or unusable keys require self-assessment. A matching key is not proof that the key is correct.</li><li>Some questions contain shared passages or refer to a preceding question. Use the original PDF for surrounding context.</li><li>Community solution links need internet. No community explanations are silently treated as official keys.</li><li>Topic mappings are editorial. A question may test more than one concept; the book’s primary subtopic is retained.</li></ul></section><h2>${corrections.length} documented note corrections</h2>${corrections.map(t=>`<a class="source-link" href="${hrefTopic(t.id)}">${esc(t.subject)} / ${esc(t.title)}</a>${correctionBox(t)}`).join('')}`;}
function settingsView(){const size=(window.GATE_ASSETS.reduce((n,a)=>n+a.bytes,0)/1048576).toFixed(0);return header('MAKE IT YOURS','Offline & backup.','Keep your study desk available and your progress portable.')+`<div class="settings-grid"><section class="panel"><h2>Keep everything offline</h2><p>The complete pack is approximately ${size} MB. Download once on each browser/device. Keep this tab open until verification finishes.</p>${location.protocol==='file:'?'<div class="notice">You are using the downloaded local copy. All included files already work without internet. Keep the extracted folder together.</div>':`<div class="button-row"><button class="primary" data-action="download-all" ${downloadJob?'disabled':''}>Download all study material</button><button class="secondary" data-action="check-offline">Check offline readiness</button></div><div class="offline-progress" id="download-status">${downloadJob?downloadJob.message:'Core notes and your progress load offline once cached. Question images and original PDFs need the complete download.'}</div>${downloadJob?'<button class="text-button top-spacer" data-action="cancel-download">Pause download</button>':''}`}<p class="small muted top-spacer">Browser storage can be cleared or evicted. Keep the downloadable app folder and progress backups for long-term access.</p><button class="secondary" data-action="install">Install / add to home screen</button><div id="install-note" class="install-note"></div></section><section class="panel"><h2>Your progress belongs to you</h2><p>Export answers, notes, bookmarks and review dates as a JSON backup. Import it on another device or after changing hosting.</p><div class="button-row"><button class="primary" data-action="export">Export progress</button><button class="secondary" data-action="import">Import backup</button></div><p class="small muted top-spacer">Progress stays in this browser. There is no account, automatic cloud sync, analytics or AI API. Import merges entries, keeping the more recently updated record.</p><div class="notice">A new website address, a different browser, and the local ZIP each have separate progress storage. Use Export → Import to move your record.</div></section><section class="panel"><h2>Reserve recent papers</h2><p>Keep recent papers fresh for future mocks.</p><label class="check-label"><input type="checkbox" data-setting="hideRecent" ${state.settings.hideRecent?'checked':''}> Hide 2024–2026 questions in topic practice</label><p>All questions remain available in the original books. Direct review and search may still show a question you explicitly open.</p></section><section class="panel"><h2>A simple daily routine</h2><ol class="help-list"><li>Clear the due review queue.</li><li>Choose one subtopic and try the recall prompt.</li><li>Read the essential idea only after trying.</li><li>Solve a few PYQs on paper, then reveal the key.</li><li>Write one memory cue and rate when to revisit.</li></ol><p>On phones, swipe question images horizontally or tap to enlarge. No subscription is required for the downloaded app.</p></section></div>`;}
function render(keepScroll=false){const scroll=window.scrollY,sideScroll=$('.sidebar')?.scrollTop||0,r=nowRoute();let body,nav=r.kind;
 if(r.kind==='subject'){if(!keepScroll)openSubject=r.id;body=subjectView(r.id);}else if(r.kind==='topic'){const t=topicMap.get(r.id);if(t&&!keepScroll)openSubject=t.subject;body=topicView(t,r.tab,r.qid);}else if(r.kind==='review')body=reviewView();else if(r.kind==='saved')body=savedView();else if(r.kind==='my-notes')body=myNotesView();else if(r.kind==='settings')body=settingsView();else if(r.kind==='sources')body=sourcesView();else if(r.kind==='search')body=searchView();else{body=dashboard();nav='home';}
 $('#app').innerHTML=shell(body,nav);if(keepScroll){window.scrollTo(0,scroll);$('.sidebar').scrollTop=sideScroll;}else window.scrollTo(0,0);
 document.querySelectorAll('img.question-image,img.source-page').forEach(img=>img.addEventListener('error',()=>{const n=document.createElement('p');n.className='notice';n.textContent='This image is not available offline yet. Reconnect and download the complete study pack in Offline & backup.';img.replaceWith(n);},{once:true}));
}
function commitDraft(){const el=$('#answer-input');if(el&&currentQ){const p=qs(currentQ);p.draft=el.value;state.questions[currentQ]=p;save();}}
function advanceReview(){reviewIndex++;revealed=false;cardReveal=false;render();}
function selectQuestion(id){commitDraft();currentQ=id;revealed=false;const r=nowRoute();history.replaceState(null,'',hrefTopic(r.id,'practice',id));render(true);}
function modal(title,content){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2 style="margin:0">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close">×</button></div><div class="dialog-body">${content}</div>`;d.showModal();}
function downloadJson(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function offlineCache(){if(location.protocol==='file:')throw Error('The extracted local app already contains its files.');if(!('caches' in window)||!('serviceWorker' in navigator))throw Error('Offline caching needs HTTPS and a browser that supports service workers.');let timer;try{await Promise.race([workerReady,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('The offline worker is not ready. Reload while online and try again.')),15000);})]);}finally{clearTimeout(timer);}return caches.open('gate-recall-assets-v1');}
function updateDownload(text,done,total){if(downloadJob)downloadJob.message=text;const el=$('#download-status');if(el)el.innerHTML=esc(text)+(total?`<progress max="${total}" value="${done}"></progress>`:'');}
async function downloadAll(){if(downloadJob)return;downloadJob={cancel:false,message:'Preparing download…'};render(true);try{const cache=await offlineCache();if(navigator.storage?.persist)await navigator.storage.persist();const assets=window.GATE_ASSETS;let i=0,done=0,failed=0;const worker=async()=>{while(i<assets.length&&!downloadJob?.cancel){const a=assets[i++],url=new URL(a.path,location.href.split('#')[0]);try{if(!(await cache.match(url))){const res=await fetch(url,{cache:'no-cache'});if(!res.ok)throw Error('Download failed');const ct=res.headers.get('Content-Type')||'';if(/\.webp$/.test(a.path)&&!ct.includes('image/'))throw Error('Expected image');if(/\.pdf$/.test(a.path)&&!ct.includes('pdf'))throw Error('Expected PDF');await cache.put(url,res);}done++;}catch(e){failed++;}updateDownload(`${done} / ${assets.length} files saved${failed?' · '+failed+' failed':''}`,done,assets.length);}};await Promise.all([worker(),worker(),worker(),worker()]);const cancelled=downloadJob?.cancel;downloadJob=null;render(true);updateDownload(cancelled?'Download paused. Saved files are kept; press download again to resume.':failed?`Saved ${done} files; ${failed} failed. Reconnect and download again to retry.`:`All ${done} files are cached. Checking readiness…`);if(!cancelled&&!failed)await checkOffline();}catch(e){downloadJob=null;render(true);updateDownload(e.message);toast(e.message);}}
async function checkOffline(){try{const c=await offlineCache(),keys=new Set((await c.keys()).map(r=>new URL(r.url).pathname));const missing=window.GATE_ASSETS.filter(a=>!keys.has(new URL(a.path,location.href.split('#')[0]).pathname));const core=await caches.open('gate-recall-core-v2');const coreKeys=await core.keys();const required=['index.html','style.css','app.js','core.js','icon.svg','icon-192.png','icon-512.png','manifest.webmanifest','data/catalog.js','data/assets.js'];const corePaths=new Set(coreKeys.map(k=>new URL(k.url).pathname));const missingCore=required.filter(p=>!corePaths.has(new URL(p,location.href.split('#')[0]).pathname));const worker=!!navigator.serviceWorker.controller;updateDownload(!missing.length&&worker&&!missingCore.length?'Ready offline: all study files are cached and the offline worker is active.':'Offline check: '+missing.length+' study files missing.'+(!worker?' Reload once to activate the offline worker.':'')+(missingCore.length?' '+missingCore.length+' app files missing; reload while online.':''));}catch(e){updateDownload(e.message);}}
async function importBackup(file){if(!file)return;if(file.size>10000000)return toast('Backup is too large; choose a GATE Recall JSON export.');try{const raw=JSON.parse(await file.text()),next=C.safeProgress(raw,new Set(qMap.keys()),new Set(topicMap.keys()));for(const type of ['questions','cards'])for(const [id,p] of Object.entries(next[type])){const old=state[type][id];if(!old||Math.max(p.updated||0,p.reviewed||0,p.attempted||0)>=Math.max(old.updated||0,old.reviewed||0,old.attempted||0))state[type][id]=p;}const sessions=new Map(state.sessions.map(s=>[s.date,s.count]));next.sessions.forEach(s=>sessions.set(s.date,Math.max(s.count,sessions.get(s.date)||0)));state.sessions=[...sessions].map(([date,count])=>({date,count}));if(typeof next.settings.hideRecent==='boolean')state.settings.hideRecent=next.settings.hideRecent;if(next.settings.initials&&(!state.settings.initials||(next.settings.initialsUpdated||0)>=(state.settings.initialsUpdated||0))){state.settings.initials=next.settings.initials;state.settings.initialsUpdated=next.settings.initialsUpdated||0;}if(next.last)state.last=next.last;save();render(true);toast('Backup merged. Your newer records were kept.');}catch(e){toast('Import failed: '+e.message);}}
$('#import-file').addEventListener('change',e=>{importBackup(e.target.files[0]);e.target.value='';});
document.addEventListener('submit',e=>{
 if(e.target.id==='search-form'){e.preventDefault();query=$('#search').value.trim();if(query){location.hash='#search';render();}}
 if(e.target.id==='profile-form'){e.preventDefault();const field=$('#profile-initials'),initials=C.normalizeInitials(field.value),error=$('#initials-error');if(!initials){error.textContent='Enter 1–3 letters or numbers.';field.focus();return;}error.textContent='';field.value=initials;state.settings.initials=initials;state.settings.initialsUpdated=Date.now();save();$('#avatar-text').textContent=initials;toast('Initials saved on this device.');}
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search'){query=el.value;return;}if(el.id==='answer-input'&&currentQ){state.questions[currentQ]={...qs(currentQ),draft:el.value,updated:Date.now()};clearTimeout(saveTimer);saveTimer=setTimeout(save,400);}if(el.dataset.noteId){const type=el.dataset.noteKind==='card'?'cards':'questions',id=el.dataset.noteId;state[type][id]={...state[type][id],note:el.value.slice(0,10000),updated:Date.now()};clearTimeout(saveTimer);saveTimer=setTimeout(()=>{save();if($('#note-saved'))$('#note-saved').textContent='Saved on this device';},400);}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){filters[el.dataset.filter]=el.value;currentQ=null;revealed=false;history.replaceState(null,'',hrefTopic(nowRoute().id,'practice'));render(true);}if(el.dataset.setting){state.settings[el.dataset.setting]=el.checked;save();toast(el.checked?'Recent papers reserved.':'All years shown in practice.');}});
document.addEventListener('click',async e=>{if(!e.target.closest('.profile-menu'))$('#profile-menu')?.removeAttribute('open');const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==='menu'){$('.sidebar').classList.toggle('open');return;}
 if(a==='subject'){openSubject=openSubject===el.dataset.name?null:el.dataset.name;if(openSubject){const target='#subject/'+encodeURIComponent(openSubject);if(location.hash===target)render(true);else location.hash=target;}else render(true);return;}
 if(a==='close-modal'){$('#modal').close();return;}
 if(a==='zoom'){modal('Original source · tap image to zoom',`<img src="${esc(el.dataset.src)}" alt="Enlarged source material" data-action="toggle-zoom">`);return;}
 if(a==='toggle-zoom'){el.classList.toggle('zoom');return;}
 if(a==='reveal-card'){cardReveal=true;render(true);return;}
 if(a==='rate'){const type=el.dataset.kind==='card'?'cards':'questions';state[type][id]={...C.schedule(state[type][id],el.dataset.rating),updated:Date.now()};logReview();save();if(isReview)advanceReview();else{cardReveal=false;revealed=false;render(true);toast('Review scheduled: '+(el.dataset.rating==='again'?'in 10 minutes':new Date(state[type][id].due).toLocaleDateString('en-IN')));}return;}
 if(a==='star-card'||a==='star-question'){const type=a==='star-card'?'cards':'questions';state[type][id]={...state[type][id],star:!state[type][id]?.star,updated:Date.now()};save();render(true);return;}
 if(a==='flag-question'){state.questions[id]={...qs(id),flag:!qs(id).flag,updated:Date.now()};save();render(true);return;}
 if(a==='choose'){const p=qs(currentQ),values=new Set((p.draft||'').split(';').filter(Boolean));if(el.dataset.multi==='true'){values.has(el.dataset.value)?values.delete(el.dataset.value):values.add(el.dataset.value);p.draft=[...values].sort().join(';');}else p.draft=el.dataset.value;p.updated=Date.now();state.questions[currentQ]=p;revealed=false;save();render(true);return;}
 if(a==='reveal-question'){commitDraft();const q=qMap.get(currentQ),p=qs(currentQ),result=C.grade(q.answer,p.draft,q.type);state.questions[currentQ]={...p,answer:p.draft||'',attempted:Date.now(),result:result===true?'correct':result===false?'wrong':p.result||'attempted',updated:Date.now()};save();revealed=true;render(true);return;}
 if(a==='mark-result'){state.questions[currentQ]={...qs(currentQ),result:el.dataset.value,attempted:Date.now(),updated:Date.now()};save();render(true);toast(el.dataset.value==='correct'?'Marked correct.':'Added to your mistakes.');return;}
 if(a==='select-q'){selectQuestion(id);return;}
 if(a==='prev-q'||a==='next-q'){const at=shownQuestions.findIndex(q=>q.id===currentQ),q=shownQuestions[at+(a==='next-q'?1:-1)];if(q)selectQuestion(q.id);return;}
 if(a==='clear-filters'){filters={paper:'All',year:'All',type:'All',status:'All'};state.settings.hideRecent=false;save();currentQ=null;revealed=false;history.replaceState(null,'',hrefTopic(nowRoute().id,'practice'));render(true);return;}
 if(a==='note-prev'||a==='note-next'){notePage+=a==='note-next'?1:-1;render(true);return;}
 if(a==='review-start'){reviewQueue=dueItems();reviewIndex=0;isReview=true;cardReveal=false;revealed=false;render();return;}
 if(a==='review-next'){advanceReview();return;}
 if(a==='review-end'){isReview=false;render();return;}
 if(a==='export'){save();downloadJson('gate-recall-progress-'+localDate()+'.json',{app:'gate-recall',version:1,exportedAt:new Date().toISOString(),state});toast('Progress backup downloaded.');return;}
 if(a==='import'){$('#import-file').click();return;}
 if(a==='download-all'){downloadAll();return;}
 if(a==='cancel-download'){if(downloadJob)downloadJob.cancel=true;return;}
 if(a==='check-offline'){checkOffline();return;}
 if(a==='install'){if(deferredInstall){await deferredInstall.prompt();deferredInstall=null;}else $('#install-note').textContent=location.protocol==='file:'?'For installation on a phone, open the hosted HTTPS version and choose Add to Home Screen. This extracted folder is already usable offline on desktop.':'In Chrome or Edge, use the address-bar install icon or menu → Install app. On Safari for iPhone, use Share → Add to Home Screen. Download the study material before going offline.';return;}
});
document.addEventListener('keydown',e=>{const typing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName);if(e.key==='/'&&!typing){e.preventDefault();$('#search')?.focus();}if(e.key==='Escape'){const profile=$('#profile-menu');if(profile?.open){profile.open=false;profile.querySelector('summary')?.focus();}$('.sidebar')?.classList.remove('open');}if((e.key==='Enter'||e.key===' ')&&document.activeElement?.dataset.action==='zoom'){e.preventDefault();document.activeElement.click();}});
window.addEventListener('hashchange',()=>{commitDraft();const r=nowRoute();if(r.kind==='topic'&&r.id!==routeKey){filters={paper:'All',year:'All',type:'All',status:'All'};currentQ=null;notePage=null;}if(r.qid)filters={paper:'All',year:'All',type:'All',status:'All'};routeKey=r.id;revealed=false;cardReveal=false;if(r.kind!=='review')isReview=false;render();});
window.addEventListener('beforeunload',save);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});
for(const event of ['online','offline'])window.addEventListener(event,()=>{if($('#connection'))$('#connection').textContent=navigator.onLine?'Device progress saved locally':'Offline mode';});
const workerReady=('serviceWorker' in navigator&&location.protocol!=='file:')?navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready):Promise.resolve(null);
workerReady.catch(()=>toast('Offline worker could not start. The local ZIP remains available.'));
render();
})();
